// 版型位置（黑本深度拆解 版面.json）：[中心x, 中心y, 寬]；前面幾格給菜（主菜、副菜），其餘給道具；完整版畫布和快速版共用
const SLOTS = {   // [中心x, 中心y, 寬, 高度級距, 'd'菜位／'p'道具位]；菜會挑高度相近的位子，高碗不會塞進小碟的位子
  '切盤・牆面留白': [[.5, .78, .9, 1, 'd'], [.82, .46, .45, 3, 'd'], [.15, .52, .2, 2, 'd'], [.33, .44, .28, 1, 'd'], [.17, .92, .3, 1, 'p'], [.9, .9, .18, 1, 'p']],
  '麵飯・同款第二碗': [[.52, .66, .8, 2, 'd'], [.8, .3, .45, 3, 'd'], [.18, .88, .22, 2, 'd'], [.2, .88, .2, 1, 'p'], [.82, .88, .3, 1, 'p'], [.72, .92, .25, 1, 'p']],
  '湯・竹墊第二碗': [[.5, .65, .86, 3, 'd'], [.85, .22, .4, 3, 'd'], [.12, .9, .22, 2, 'd'], [.5, .8, 1.1, 1, 'p'], [.7, .86, .2, 1, 'p'], [.25, .3, .2, 1, 'p']],
  '鍋・滿版出血': [[.5, .55, .95, 3, 'd'], [.1, .85, .28, 3, 'd'], [.88, .92, .3, 2, 'd'], [.12, .2, .4, 3, 'p'], [.5, .75, 1.1, 1, 'p'], [.9, .3, .2, 1, 'p']],
};
// 把菜和道具分配到版型位子：菜先挑同高度的菜位，沒有就挑任一菜位；道具用剩下的位子；多出來的回傳 null（由呼叫端排到邊上）
function assignSlots(space, mainDish, dishes, props) {
  const sl = (slotsFor(space, mainDish) || []).map(s => ({ x: s[0], y: s[1], w: s[2], h: s[3], k: s[4], used: false })), out = {};
  const take = (pred) => { const s = sl.find(x => !x.used && pred(x)); if (s) s.used = true; return s; };
  dishes.forEach((d, i) => { const h = dishHeight(d); const s = i === 0 ? take(x => x.k === 'd') : take(x => x.k === 'd' && x.h === h) || take(x => x.k === 'd') || take(x => x.k === 'p' && x.h === h); out[d] = s ? { x: s.x, y: s.y, w: s.w } : null; });
  props.forEach(n => { const s = take(x => x.k === 'p') || take(() => true); out[n] = s ? { x: s.x, y: s.y, w: Math.min(s.w, .22) } : null; });
  return out;
}
// 依主菜建議版型：切盤類→切盤；麵飯→麵飯；湯→湯；鍋→鍋
const spaceFor = dish => /鍋/.test(dish) ? '鍋・滿版出血' : /湯/.test(dish) ? '湯・竹墊第二碗' : /麵|飯|冬粉|炒手/.test(dish) ? '麵飯・同款第二碗' : '切盤・牆面留白';

// 器皿高度（公分級距）：1＝平盤、2＝淺碗／小碟、3＝高碗／鍋／杯。排版用：前面的東西只能遮後面「不超過自己高度」的部分
const DISH_HEIGHT = [[/湯|麵|飯|冬粉|鍋|杯|甕|罐/, 3], [/切盤|白肉|魚皮|時蔬|地瓜葉|高麗菜|豆芽|砧板|托盤|竹簾|價目牌|菜刀|蒜瓣|薑片|蔥段|海鹽|筷|湯匙|湯勺/, 1]];
const dishHeight = name => (DISH_HEIGHT.find(([re]) => re.test(name)) || [0, 2])[1];
// 把疊錯的東西移開：items＝[{key,x,y,w,h,dish}]（畫面比例；y＝中心；h＝高度級距；dish＝是菜）；wh＝畫面寬÷高（換算橢圓在 y 方向的高度）
// 允許的遮擋：前矮後高 10%、同高 30%、前高後矮 不限。菜被壓到→後面的菜往上移；道具壓到菜→道具往下移（道具不能推菜）
function fixStacking(items, wh = .8) {
  const box = it => { const hh = it.w * .55 * wh / 2; return { top: it.y - hh, bot: it.y + hh, l: it.x - it.w / 2, r: it.x + it.w / 2 }; };
  const moved = [];
  for (let pass = 0; pass < 4; pass++) items.slice().sort((a, b) => b.y - a.y).forEach(front => items.forEach(back => {
    if (back === front || back.y >= front.y) return;
    const f = box(front), b = box(back); if (b.r <= f.l || b.l >= f.r) return;
    const allow = back.h < front.h ? 1 : back.h > front.h ? .1 : .3, over = b.bot - f.top, lim = allow * (b.bot - b.top);
    if (over <= lim + .005) return;
    const mv = (!front.dish && back.dish) ? front : back;   // 道具擋到菜：移道具
    mv.y = +Math.min(.97, Math.max(.03, mv === front ? mv.y + (over - lim) : mv.y - (over - lim))).toFixed(3);
    if (!moved.includes(mv.key)) moved.push(mv.key);
  }));
  return moved;
}
// 主菜是平盤卻選了湯、鍋這種「高碗在前」的版型：平盤壓不住後排，改用切盤版型的位置
const slotsFor = (space, mainDish) => { const t = CHOICES.空間.find(x => x.name === space); return (t && t.main === 3 && dishHeight(mainDish || '') === 1) ? SLOTS['切盤・牆面留白'] : SLOTS[space]; };
